:root {
  --bg1: #071421;
  --bg2: #101c2a;
  --panel: rgba(10, 18, 29, 0.82);
  --panel-border: rgba(100, 160, 255, 0.42);
  --text: #edf6ff;
  --muted: #a7bbd6;
  --accent: #64d9ff;
  --accent2: #ff8fbf;
  --success: #8bf4b1;
  --danger: #ff7a7a;
  --warning: #f7d78d;
  --heel: #d67cff;
  --shop: #00d1b7;
}

* {
  box-sizing: border-box;
}

html, body {
  margin: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: radial-gradient(circle at top, #1b2b37 0%, var(--bg1) 40%, #040b12 100%);
  color: var(--text);
  font-family: Inter, "Segoe UI", sans-serif;
}

body {
  display: grid;
  place-items: center;
}

.app-shell {
  position: relative;
  width: min(96vw, 1200px);
  height: min(92vh, 720px);
  border-radius: 24px;
  border: 1px solid rgba(148, 177, 255, 0.26);
  overflow: hidden;
  background: linear-gradient(180deg, rgba(19, 28, 40, 0.84), rgba(9, 13, 21, 0.9));
  box-shadow: 0 25px 80px rgba(0, 0, 0, 0.45);
}

#gameCanvas {
  width: 100%;
  height: 100%;
  display: block;
  background: linear-gradient(180deg, #0e1d2d 0%, #0a1620 100%);
}

.hud {
  position: absolute;
  top: 18px;
  left: 18px;
  right: 18px;
  display: flex;
  flex-direction: column;
  gap: 12px;
  pointer-events: none;
}

.top-bar {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

.pill {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: var(--panel);
  border: 1px solid var(--panel-border);
  border-radius: 999px;
  padding: 8px 14px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.2);
  backdrop-filter: blur(12px);
}

.pill .label {
  color: var(--muted);
  font-size: 12px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.pill strong {
  font-size: 15px;
}

.money-pill {
  background: rgba(25, 61, 53, 0.72);
  border-color: rgba(114, 255, 198, 0.5);
}

.status-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(180px, 1fr));
  gap: 12px;
  max-width: 500px;
}

.meter-wrap {
  padding: 10px 12px 8px;
  border-radius: 14px;
  background: rgba(13, 21, 31, 0.72);
  border: 1px solid rgba(133, 167, 237, 0.24);
}

.meter-label-row {
  display: flex;
  justify-content: space-between;
  font-size: 12px;
  color: var(--muted);
  margin-bottom: 8px;
}

.meter {
  position: relative;
  height: 12px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.07);
  overflow: hidden;
}

.meter-fill {
  position: absolute;
  inset: 0 auto 0 0;
  width: 100%;
  border-radius: inherit;
  transition: width 0.18s ease;
}

.heel-fill {
  background: linear-gradient(90deg, #ff8bd7, #d67cff, #a777ff);
}

.energy-fill {
  background: linear-gradient(90deg, #5be7ff, #62ffc8);
}

.mission-log {
  width: min(100%, 360px);
  padding: 12px 14px;
  border-radius: 14px;
  background: rgba(8, 17, 25, 0.74);
  border: 1px solid rgba(129, 177, 255, 0.25);
  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.18);
  pointer-events: none;
}

.log-title {
  font-size: 11px;
  letter-spacing: 0.12em;
  color: var(--accent);
  text-transform: uppercase;
  margin-bottom: 6px;
}

.mission-log p {
  margin: 0;
  color: var(--text);
  line-height: 1.5;
  font-size: 13px;
}

.message-box {
  position: absolute;
  left: 50%;
  bottom: 56px;
  transform: translateX(-50%);
  min-width: min(70vw, 480px);
  background: rgba(12, 17, 25, 0.86);
  border: 1px solid rgba(209, 229, 255, 0.18);
  border-radius: 16px;
  padding: 18px 22px;
  font-size: 15px;
  text-align: center;
  color: var(--text);
  box-shadow: 0 18px 36px rgba(0, 0, 0, 0.25);
}

.hidden {
  display: none !important;
}

.restart {
  position: absolute;
  left: 50%;
  bottom: 20px;
  transform: translateX(-50%);
  border: 0;
  border-radius: 999px;
  background: linear-gradient(135deg, #6fe2ff, #7aa2ff);
  color: #061720;
  padding: 12px 22px;
  font-weight: 800;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  cursor: pointer;
  box-shadow: 0 10px 28px rgba(100, 180, 255, 0.5);
}

@media (max-width: 720px) {
  .app-shell {
    width: 100vw;
    height: 100vh;
    border-radius: 0;
  }

  .hud {
    top: 12px;
    left: 12px;
    right: 12px;
  }

  .top-bar {
    gap: 8px;
  }

  .pill {
    padding: 7px 10px;
  }

  .status-grid {
    grid-template-columns: 1fr;
    max-width: 100%;
  }

  .mission-log {
    width: min(100%, 240px);
  }
}

const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');

const missionText = document.getElementById('missionText');
const missionLog = document.getElementById('missionLog');
const heelValue = document.getElementById('heelValue');
const energyValue = document.getElementById('energyValue');
const heelBar = document.getElementById('heelBar');
const energyBar = document.getElementById('energyBar');
const moneyText = document.getElementById('moneyText');
const messageBox = document.getElementById('messageBox');
const restartBtn = document.getElementById('restartBtn');

const world = { width: 2200, height: 2200 };
const keys = {};
const markerRadius = 30;
const buildingRects = [
  { x: 300, y: 230, w: 280, h: 180, color: '#1d3557' },
  { x: 760, y: 210, w: 340, h: 220, color: '#2b446d' },
  { x: 1260, y: 190, w: 340, h: 260, color: '#243e59' },
  { x: 1700, y: 250, w: 260, h: 200, color: '#223d53' },
  { x: 220, y: 720, w: 260, h: 220, color: '#1b2d47' },
  { x: 650, y: 760, w: 330, h: 200, color: '#254266' },
  { x: 1200, y: 760, w: 370, h: 240, color: '#1f3f5e' },
  { x: 1740, y: 760, w: 260, h: 220, color: '#1d3b4d' },
  { x: 260, y: 1280, w: 320, h: 220, color: '#2d4055' },
  { x: 760, y: 1280, w: 340, h: 220, color: '#24375f' },
  { x: 1280, y: 1250, w: 340, h: 220, color: '#22415b' },
  { x: 1770, y: 1280, w: 250, h: 220, color: '#1e3746' },
  { x: 430, y: 1760, w: 360, h: 180, color: '#304d67' },
  { x: 1020, y: 1780, w: 360, h: 170, color: '#213d52' },
  { x: 1510, y: 1770, w: 340, h: 190, color: '#214966' }
];

const shop = { x: 1080, y: 550, radius: 90 };

const suspectSpawns = [
  { x: 490, y: 510, radius: 18, name: 'Rooftop thief' },
  { x: 1520, y: 420, radius: 18, name: 'Stolen bike gang' },
  { x: 980, y: 1480, radius: 18, name: 'Counterfeit ring' },
  { x: 1820, y: 990, radius: 18, name: 'Bodega arson' },
  { x: 650, y: 1800, radius: 18, name: 'Extortion crew' }
];

const evidenceSpawns = [
  { x: 340, y: 930, radius: 14, type: 'cash trace' },
  { x: 820, y: 470, radius: 14, type: 'phone signal' },
  { x: 1490, y: 1010, radius: 14, type: 'lockpick kit' },
  { x: 1810, y: 1650, radius: 14, type: 'stolen invoice' },
  { x: 1120, y: 1950, radius: 14, type: 'tracked bag' }
];

const game = {
  lastTime: 0,
  active: true,
  time: 0,
  worldShiftX: 0,
  worldShiftY: 0,
  money: Infinity,
  missionIndex: 0,
  objectivesCleared: 0,
  currentMessage: '',
  messageTimer: 0,
  missionState: 'Patrol the city'
};

const player = {
  x: 1080,
  y: 540,
  radius: 18,
  speed: 220,
  energy: 100,
  heelIntegrity: 100,
  direction: 0,
  invulnerable: 0,
  canMove: true,
  attire: 'Black heels'
};

const worldState = {
  suspects: suspectSpawns.map((item) => ({ ...item, captured: false })),
  evidence: evidenceSpawns.map((item) => ({ ...item, collected: false })),
  objectiveText: 'Escort the petition run and check all hotspots.'
};

const camera = { x: 0, y: 0 };

restartBtn.addEventListener('click', resetGame);

document.addEventListener('keydown', (event) => {
  keys[event.key.toLowerCase()] = true;
  if (event.key === 'e' || event.key === 'E') handleInteraction();
  if (event.key === ' ') {
    event.preventDefault();
    handleInteraction();
  }
});

document.addEventListener('keyup', (event) => {
  keys[event.key.toLowerCase()] = false;
});

function resetGame() {
  player.x = 1080;
  player.y = 540;
  player.energy = 100;
  player.heelIntegrity = 100;
  player.canMove = true;
  game.active = true;
  game.time = 0;
  game.missionIndex = 0;
  game.objectivesCleared = 0;
  messageBox.classList.add('hidden');
  restartBtn.classList.add('hidden');
  worldState.suspects = suspectSpawns.map((item) => ({ ...item, captured: false }));
  worldState.evidence = evidenceSpawns.map((item) => ({ ...item, collected: false }));
  updateMissionText('Patrol the city');
  updateLog('Downtown is active. Keep the heels steady and the city safe.');
  setMessage('Shift started. Keep moving.');
}

function clamp(value, min, max) {
  return Math.min(max, Math.max(min, value));
}

function distance(aX, aY, bX, bY) {
  return Math.hypot(aX - bX, aY - bY);
}

function setMessage(msg) {
  messageBox.textContent = msg;
  messageBox.classList.remove('hidden');
  game.messageTimer = 2.4;
}

function updateMissionText(text) {
  missionText.textContent = text;
}

function updateLog(text) {
  missionLog.innerHTML = `<div class="log-title">Dispatch</div><p>${text}</p>`;
}

function handleInteraction() {
  if (distance(player.x, player.y, shop.x, shop.y) < shop.radius + 26) {
    if (player.heelIntegrity < 100 || player.energy < 100) {
      player.heelIntegrity = 100;
      player.energy = 100;
      setMessage('New heels fitted. Officer back in motion.');
      updateLog('Shoe store restocked. Heel replacement completed before the next alert.');
      return;
    }

    setMessage('Heels and energy already at full strength.');
    return;
  }

  const suspect = worldState.suspects.find((s) => !s.captured && distance(player.x, player.y, s.x, s.y) < 42);
  if (suspect) {
    suspect.captured = true;
    game.objectivesCleared += 1;
    setMessage(`Suspect caught: ${suspect.name}.`);
    updateLog(`Suspect neutralized: ${suspect.name}. Patrol route is holding.');
    checkCompletion();
  }

  const evidence = worldState.evidence.find((e) => !e.collected && distance(player.x, player.y, e.x, e.y) < 34);
  if (evidence) {
    evidence.collected = true;
    setMessage(`Evidence secured: ${evidence.type}.`);
    updateLog(`Recovered ${evidence.type}. Every clue strengthens the case.`);
    checkCompletion();
  }
}

function checkCompletion() {
  const allSuspectsCaught = worldState.suspects.every((s) => s.captured);
  const allEvidenceCollected = worldState.evidence.every((e) => e.collected);

  if (allSuspectsCaught && allEvidenceCollected) {
    updateMissionText('Shift complete');
    updateLog('City secured. All suspects are accounted for and the evidence trail is closed.');
    setMessage('Mission complete. The city is safe tonight.');
    game.active = false;
    restartBtn.classList.remove('hidden');
  }
}

function updatePlayer(dt) {
  if (!player.canMove) return;

  let moveX = 0;
  let moveY = 0;

  if (keys['w'] || keys['arrowup']) moveY -= 1;
  if (keys['s'] || keys['arrowdown']) moveY += 1;
  if (keys['a'] || keys['arrowleft']) moveX -= 1;
  if (keys['d'] || keys['arrowright']) moveX += 1;

  const length = Math.hypot(moveX, moveY) || 1;
  if (moveX !== 0 || moveY !== 0) {
    const adjustedSpeed = player.speed * (player.energy > 15 ? 1 : 0.65);
    const dx = (moveX / length) * adjustedSpeed * dt;
    const dy = (moveY / length) * adjustedSpeed * dt;

    player.x += dx;
    player.y += dy;
    player.direction = Math.atan2(moveY, moveX);

    player.energy = clamp(player.energy - dt * 2.8, 0, 100);
  } else {
    player.energy = clamp(player.energy + dt * 3.8, 0, 100);
  }

  player.x = clamp(player.x, 45, world.width - 45);
  player.y = clamp(player.y, 45, world.height - 45);

  const touchingBuilding = buildingRects.some((rect) =>
    player.x + player.radius > rect.x &&
    player.x - player.radius < rect.x + rect.w &&
    player.y + player.radius > rect.y &&
    player.y - player.radius < rect.y + rect.h
  );

  if (touchingBuilding) {
    if (player.invulnerable <= 0) {
      player.heelIntegrity = clamp(player.heelIntegrity - 7, 0, 100);
      player.invulnerable = 0.4;
    }
    player.x = clamp(player.x - Math.cos(player.direction || 0) * 25, 50, world.width - 50);
    player.y = clamp(player.y - Math.sin(player.direction || 0) * 25, 50, world.height - 50);
  }

  if (player.heelIntegrity <= 0) {
    player.canMove = false;
    if (distance(player.x, player.y, shop.x, shop.y) < shop.radius + 30) {
      player.canMove = true;
    }
    setMessage('Heels damaged. Head to the shoe shop to repair them.');
    updateLog('The left heel snapped. Shop repair is required before continuing the chase.');
  }

  if (player.energy <= 0) {
    player.energy = 0;
    player.speed = 120;
  } else {
    player.speed = 220;
  }

  if (player.invulnerable > 0) {
    player.invulnerable -= dt;
  }

  if (player.heelIntegrity > 0 && distance(player.x, player.y, shop.x, shop.y) < shop.radius + 40) {
    player.canMove = true;
  }
}

function updateCamera() {
  const viewportWidth = canvas.width;
  const viewportHeight = canvas.height;
  camera.x = clamp(player.x - viewportWidth / 2, 0, world.width - viewportWidth);
  camera.y = clamp(player.y - viewportHeight / 2, 0, world.height - viewportHeight);
}

function drawBackground() {
  ctx.fillStyle = '#0b1720';
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  ctx.save();
  ctx.translate(-camera.x, -camera.y);

  for (let x = 0; x < world.width; x += 80) {
    for (let y = 0; y < world.height; y += 80) {
      ctx.fillStyle = (x + y) % 160 === 0 ? '#101d2b' : '#0f1a26';
      ctx.fillRect(x, y, 80, 80);
    }
  }

  ctx.strokeStyle = 'rgba(160, 200, 255, 0.22)';
  ctx.lineWidth = 2;
  for (let i = 0; i < 6; i++) {
    const x = 220 + i * 330;
    ctx.beginPath();
    ctx.moveTo(x, 0);
    ctx.lineTo(x, world.height);
    ctx.stroke();
  }

  for (let i = 0; i < 6; i++) {
    const y = 150 + i * 340;
    ctx.beginPath();
    ctx.moveTo(0, y);
    ctx.lineTo(world.width, y);
    ctx.stroke();
  }

  for (const rect of buildingRects) {
    ctx.fillStyle = rect.color;
    ctx.fillRect(rect.x, rect.y, rect.w, rect.h);
    ctx.fillStyle = 'rgba(255,255,255,0.06)';
    ctx.fillRect(rect.x + 25, rect.y + 24, rect.w - 50, 18);
    ctx.fillRect(rect.x + 25, rect.y + rect.h - 34, rect.w - 50, 12);
  }

  ctx.fillStyle = '#5ce7d9';
  ctx.beginPath();
  ctx.arc(shop.x, shop.y, shop.radius, 0, Math.PI * 2);
  ctx.fill();

  ctx.fillStyle = '#12475c';
  ctx.fillRect(shop.x - 32, shop.y - 14, 64, 28);
  ctx.fillStyle = '#d9f9ff';
  ctx.fillRect(shop.x - 18, shop.y - 26, 10, 20);
  ctx.fillRect(shop.x + 8, shop.y - 26, 10, 20);

  for (const suspect of worldState.suspects) {
    if (suspect.captured) continue;
    ctx.fillStyle = '#ff646e';
    ctx.beginPath();
    ctx.arc(suspect.x, suspect.y, suspect.radius, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = '#ffd7dd';
    ctx.fillRect(suspect.x - 12, suspect.y - 26, 24, 10);
  }

  for (const item of worldState.evidence) {
    if (item.collected) continue;
    ctx.fillStyle = '#f7d85c';
    ctx.beginPath();
    ctx.arc(item.x, item.y, item.radius, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = '#533f00';
    ctx.fillRect(item.x - 2, item.y - 20, 4, 40);
    ctx.fillRect(item.x - 16, item.y - 2, 32, 4);
  }

  ctx.restore();
}

function drawPlayer() {
  const x = player.x - camera.x;
  const y = player.y - camera.y;

  ctx.save();
  ctx.translate(x, y);

  ctx.fillStyle = 'rgba(0,0,0,0.18)';
  ctx.beginPath();
  ctx.ellipse(0, 26, 18, 8, 0, 0, Math.PI * 2);
  ctx.fill();

  ctx.fillStyle = '#f6d3d6';
  ctx.beginPath();
  ctx.arc(0, -30, 18, 0, Math.PI * 2);
  ctx.fill();

  ctx.fillStyle = '#0a0b12';
  ctx.beginPath();
  ctx.arc(-5, -34, 3.5, 0, Math.PI * 2);
  ctx.arc(5, -34, 3.5, 0, Math.PI * 2);
  ctx.fill();

  ctx.strokeStyle = '#3b261d';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(-8, -16);
  ctx.lineTo(-4, 6);
  ctx.moveTo(8, -16);
  ctx.lineTo(4, 6);
  ctx.stroke();

  ctx.fillStyle = '#1c1d20';
  ctx.fillRect(-16, -8, 32, 30);

  ctx.strokeStyle = '#d6b9ff';
  ctx.lineWidth = 5;
  ctx.beginPath();
  ctx.moveTo(-10, 22);
  ctx.lineTo(-2, 38);
  ctx.moveTo(10, 22);
  ctx.lineTo(2, 38);
  ctx.stroke();

  ctx.fillStyle = '#0d0b12';
  ctx.fillRect(-15, 24, 6, 20);
  ctx.fillRect(9, 24, 6, 20);

  ctx.restore();
}

function drawWorldMarkers() {
  ctx.save();
  ctx.translate(-camera.x, -camera.y);

  const target = worldState.suspects.find((s) => !s.captured) || worldState.evidence.find((e) => !e.collected);
  const markerTarget = target || { x: shop.x, y: shop.y };

  ctx.strokeStyle = 'rgba(147, 226, 255, 0.8)';
  ctx.lineWidth = 2;
  ctx.beginPath();
  ctx.arc(markerTarget.x, markerTarget.y, markerRadius, 0, Math.PI * 2);
  ctx.stroke();

  ctx.fillStyle = 'rgba(147, 226, 255, 0.18)';
  ctx.beginPath();
  ctx.arc(markerTarget.x, markerTarget.y, markerRadius - 8, 0, Math.PI * 2);
  ctx.fill();

  ctx.restore();
}

function drawHudEffects() {
  const viewX = player.x - camera.x;
  const viewY = player.y - camera.y;

  if (player.invulnerable > 0) {
    ctx.strokeStyle = 'rgba(255, 123, 149, 0.7)';
    ctx.beginPath();
    ctx.arc(viewX, viewY, player.radius + 10, 0, Math.PI * 2);
    ctx.stroke();
  }

  const shopDist = distance(player.x, player.y, shop.x, shop.y);
  if (shopDist < shop.radius + 40) {
    ctx.fillStyle = 'rgba(96, 255, 217, 0.16)';
    ctx.beginPath();
    ctx.arc(shop.x - camera.x, shop.y - camera.y, 92, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = '#99ffeb';
    ctx.font = '18px sans-serif';
    ctx.fillText('Press E to repair heels', shop.x - camera.x - 85, shop.y - camera.y - 95);
  }
}

function updateUi() {
  const heelPct = Math.max(0, player.heelIntegrity);
  const energyPct = Math.max(0, player.energy);

  heelValue.textContent = `${Math.round(heelPct)}%`;
  energyValue.textContent = `${Math.round(energyPct)}%`;
  heelBar.style.width = `${heelPct}%`;
  energyBar.style.width = `${energyPct}%`;
  moneyText.textContent = '∞';

  if (player.heelIntegrity <= 30) {
    heelBar.style.background = 'linear-gradient(90deg, #ff9f6e, #ff5d73)';
  } else {
    heelBar.style.background = 'linear-gradient(90deg, #ff8bd7, #d67cff, #a777ff)';
  }
}

function update(dt) {
  if (game.messageTimer > 0) {
    game.messageTimer -= dt;
    if (game.messageTimer <= 0) {
      messageBox.classList.add('hidden');
    }
  }

  if (game.active) {
    updatePlayer(dt);
  }

  updateCamera();
  updateUi();
}

function render() {
  drawBackground();
  drawWorldMarkers();
  drawPlayer();
  drawHudEffects();
}

let lastFrame = 0;
function tick(timestamp) {
  const dt = Math.min((timestamp - lastFrame) / 1000 || 0.016, 0.033);
  lastFrame = timestamp;
  game.time += dt;
  update(dt);
  render();
  requestAnimationFrame(tick);
}

resetGame();
requestAnimationFrame(tick);

