245:     player.speed = 120;
246:   } else {
247:     player.speed = 220;
248:   }
249: 
250:   if (player.invulnerable > 0) {
251:     player.invulnerable -= dt;
252:   }
253: 
254:   if (player.heelIntegrity > 0 && distance(player.x, player.y, shop.x, shop.y) < shop.radius + 40) {
255:     player.canMove = true;
256:   }
257: }
258: 
259: function updateCamera() {
260:   const viewportWidth = canvas.width;
261:   const viewportHeight = canvas.height;
262:   camera.x = clamp(player.x - viewportWidth / 2, 0, world.width - viewportWidth);
263:   camera.y = clamp(player.y - viewportHeight / 2, 0, world.height - viewportHeight);
264: }
265: 
266: function drawBackground() {
267:   ctx.fillStyle = '#0b1720';
268:   ctx.fillRect(0, 0, canvas.width, canvas.height);
269: 
270:   ctx.save();
271:   ctx.translate(-camera.x, -camera.y);
272: 
273:   for (let x = 0; x < world.width; x += 80) {
274:     for (let y = 0; y < world.height; y += 80) {
275:       ctx.fillStyle = (x + y) % 160 === 0 ? '#101d2b' : '#0f1a26';
276:       ctx.fillRect(x, y, 80, 80);
277:     }
278:   }
279: 
280:   ctx.strokeStyle = 'rgba(160, 200, 255, 0.22)';
281:   ctx.lineWidth = 2;
282:   for (let i = 0; i < 6; i++) {
283:     const x = 220 + i * 330;
284:     ctx.beginPath();
285:     ctx.moveTo(x, 0);
286:     ctx.lineTo(x, world.height);
287:     ctx.stroke();
288:   }
289: 
290:   for (let i = 0; i < 6; i++) {
291:     const y = 150 + i * 340;
292:     ctx.beginPath();
293:     ctx.moveTo(0, y);
294:     ctx.lineTo(world.width, y);
295:     ctx.stroke();
296:   }
297: 
298:   for (const rect of buildingRects) {
299:     ctx.fillStyle = rect.color;
300:     ctx.fillRect(rect.x, rect.y, rect.w, rect.h);
301:     ctx.fillStyle = 'rgba(255,255,255,0.06)';
302:     ctx.fillRect(rect.x + 25, rect.y + 24, rect.w - 50, 18);
303:     ctx.fillRect(rect.x + 25, rect.y + rect.h - 34, rect.w - 50, 12);
304:   }
305: 
306:   ctx.fillStyle = '#5ce7d9';
307:   ctx.beginPath();
308:   ctx.arc(shop.x, shop.y, shop.radius, 0, Math.PI * 2);
309:   ctx.fill();
310: 
311:   ctx.fillStyle = '#12475c';
312:   ctx.fillRect(shop.x - 32, shop.y - 14, 64, 28);
313:   ctx.fillStyle = '#d9f9ff';
314:   ctx.fillRect(shop.x - 18, shop.y - 26, 10, 20);
315:   ctx.fillRect(shop.x + 8, shop.y - 26, 10, 20);
316: 
317:   for (const suspect of worldState.suspects) {
318:     if (suspect.captured) continue;
319:     ctx.fillStyle = '#ff646e';
320:     ctx.beginPath();
321:     ctx.arc(suspect.x, suspect.y, suspect.radius, 0, Math.PI * 2);
322:     ctx.fill();
323:     ctx.fillStyle = '#ffd7dd';
324:     ctx.fillRect(suspect.x - 12, suspect.y - 26, 24, 10);
325:   }
326: 
327:   for (const item of worldState.evidence) {
328:     if (item.collected) continue;
329:     ctx.fillStyle = '#f7d85c';
330:     ctx.beginPath();
331:     ctx.arc(item.x, item.y, item.radius, 0, Math.PI * 2);
332:     ctx.fill();
333:     ctx.fillStyle = '#533f00';
334:     ctx.fillRect(item.x - 2, item.y - 20, 4, 40);
335:     ctx.fillRect(item.x - 16, item.y - 2, 32, 4);
336:   }
337: 
338:   ctx.restore();
339: }
340: 
341: function drawPlayer() {
342:   const x = player.x - camera.x;
343:   const y = player.y - camera.y;
344: 
345:   ctx.save();
346:   ctx.translate(x, y);
347: 
348:   ctx.fillStyle = 'rgba(0,0,0,0.18)';
349:   ctx.beginPath();
350:   ctx.ellipse(0, 26, 18, 8, 0, 0, Math.PI * 2);
351:   ctx.fill();
352: 
353:   ctx.fillStyle = '#f6d3d6';
354:   ctx.beginPath();
355:   ctx.arc(0, -30, 18, 0, Math.PI * 2);
356:   ctx.fill();
357: 
358:   ctx.fillStyle = '#0a0b12';
359:   ctx.beginPath();
360:   ctx.arc(-5, -34, 3.5, 0, Math.PI * 2);
361:   ctx.arc(5, -34, 3.5, 0, Math.PI * 2);
362:   ctx.fill();
363: 
364:   ctx.strokeStyle = '#3b261d';
365:   ctx.lineWidth = 3;
366:   ctx.beginPath();
367:   ctx.moveTo(-8, -16);
368:   ctx.lineTo(-4, 6);
369:   ctx.moveTo(8, -16);
370:   ctx.lineTo(4, 6);
371:   ctx.stroke();
372: 
373:   ctx.fillStyle = '#1c1d20';
374:   ctx.fillRect(-16, -8, 32, 30);
375: 
376:   ctx.strokeStyle = '#d6b9ff';
377:   ctx.lineWidth = 5;
378:   ctx.beginPath();
379:   ctx.moveTo(-10, 22);
380:   ctx.lineTo(-2, 38);
381:   ctx.moveTo(10, 22);
382:   ctx.lineTo(2, 38);
383:   ctx.stroke();
384: 
385:   ctx.fillStyle = '#0d0b12';
386:   ctx.fillRect(-15, 24, 6, 20);
387:   ctx.fillRect(9, 24, 6, 20);
388: 
389:   ctx.restore();
390: }
391: 
392: function drawWorldMarkers() {
393:   ctx.save();
394:   ctx.translate(-camera.x, -camera.y);
395: 
396:   const target = worldState.suspects.find((s) => !s.captured) || worldState.evidence.find((e) => !e.collected);
397:   const markerTarget = target || { x: shop.x, y: shop.y };
398: 
399:   ctx.strokeStyle = 'rgba(147, 226, 255, 0.8)';
400:   ctx.lineWidth = 2;
401:   ctx.beginPath();
402:   ctx.arc(markerTarget.x, markerTarget.y, markerRadius, 0, Math.PI * 2);
403:   ctx.stroke();
404: 
405:   ctx.fillStyle = 'rgba(147, 226, 255, 0.18)';
406:   ctx.beginPath();
407:   ctx.arc(markerTarget.x, markerTarget.y, markerRadius - 8, 0, Math.PI * 2);
408:   ctx.fill();
409: 
410:   ctx.restore();
411: }
412: 
413: function drawHudEffects() {
414:   const viewX = player.x - camera.x;
415:   const viewY = player.y - camera.y;
416: 
417:   if (player.invulnerable > 0) {
418:     ctx.strokeStyle = 'rgba(255, 123, 149, 0.7)';
419:     ctx.beginPath();
420:     ctx.arc(viewX, viewY, player.radius + 10, 0, Math.PI * 2);
421:     ctx.stroke();
422:   }
423: 
424:   const shopDist = distance(player.x, player.y, shop.x, shop.y);
425:   if (shopDist < shop.radius + 40) {
426:     ctx.fillStyle = 'rgba(96, 255, 217, 0.16)';
427:     ctx.beginPath();
428:     ctx.arc(shop.x - camera.x, shop.y - camera.y, 92, 0, Math.PI * 2);
429:     ctx.fill();
430:     ctx.fillStyle = '#99ffeb';
431:     ctx.font = '18px sans-serif';
432:     ctx.fillText('Press E to repair heels', shop.x - camera.x - 85, shop.y - camera.y - 95);
433:   }
434: }
435: 
436: function updateUi() {
437:   const heelPct = Math.max(0, player.heelIntegrity);
438:   const energyPct = Math.max(0, player.energy);
439: 
440:   heelValue.textContent = `${Math.round(heelPct)}%`;
441:   energyValue.textContent = `${Math.round(energyPct)}%`;
442:   heelBar.style.width = `${heelPct}%`;
443:   energyBar.style.width = `${energyPct}%`;
444:   moneyText.textContent = '∞';
445: 
446:   if (player.heelIntegrity <= 30) {
447:     heelBar.style.background = 'linear-gradient(90deg, #ff9f6e, #ff5d73)';
448:   } else {
449:     heelBar.style.background = 'linear-gradient(90deg, #ff8bd7, #d67cff, #a777ff)';
450:   }
451: }
452: 
453: function update(dt) {
454:   if (game.messageTimer > 0) {
455:     game.messageTimer -= dt;
456:     if (game.messageTimer <= 0) {
457:       messageBox.classList.add('hidden');
458:     }
459:   }
460: 
461:   if (game.active) {
462:     updatePlayer(dt);
463:   }
464: 
465:   updateCamera();
466:   updateUi();
467: }
468: 
469: function render() {
470:   drawBackground();
471:   drawWorldMarkers();
472:   drawPlayer();
473:   drawHudEffects();
474: }
475: 
476: let lastFrame = 0;
477: function tick(timestamp) {
478:   const dt = Math.min((timestamp - lastFrame) / 1000 || 0.016, 0.033);
479:   lastFrame = timestamp;
480:   game.time += dt;
481:   update(dt);
482:   render();
483:   requestAnimationFrame(tick);
484: }
485: 
486: resetGame();
487: requestAnimationFrame(tick);

